/* Pinoform — 3D-коробка на шипах для головної.
   Тягнути мишкою/пальцем — крутити, натиснути — відкрити/закрити кришку.
   Без WebGL або без three.js лишається статична картинка (постер). */
window.pfBox3d = function () {
  "use strict";
  if (window.__pfBox3dDone || !window.THREE || !window.PF_BOX3D) return;
  var host = document.getElementById("box3d");
  if (!host) return;
  window.__pfBox3dDone = true;

  var T = window.THREE, D = window.PF_BOX3D;
  var canvas = host.querySelector("canvas");
  var renderer;
  try {
    renderer = new T.WebGLRenderer({ canvas: canvas, antialias: true, alpha: true });
  } catch (e) { return; }
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = T.PCFSoftShadowMap;

  var L = D.size[0], W = D.size[1], H = D.size[2], TH = D.size[3];
  var scene = new T.Scene();
  var camera = new T.PerspectiveCamera(26, 1, 10, 10000);

  // світло: м'яке небо + основне зліва-згори з тінню + слабке заповнення справа
  scene.add(new T.HemisphereLight(0xffffff, 0xe4e7eb, 0.72));
  var key = new T.DirectionalLight(0xffffff, 0.38);
  key.position.set(-560, 1000, 700);
  key.castShadow = true;
  key.shadow.mapSize.set(1024, 1024);
  var sc = key.shadow.camera;
  sc.left = -560; sc.right = 560; sc.top = 560; sc.bottom = -560; sc.near = 200; sc.far = 3200;
  key.shadow.bias = -0.0005;
  key.shadow.radius = 3;
  scene.add(key);
  var fill = new T.DirectionalLight(0xffffff, 0.11);
  fill.position.set(800, 300, -300);
  scene.add(fill);

  var ground = new T.Mesh(new T.PlaneGeometry(6000, 6000), new T.ShadowMaterial({ opacity: 0.09 }));
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);

  // текстура пінопласту: кульки (комірки Вороного), безшовна
  function beadTexture(size, n) {
    var c = document.createElement("canvas");
    c.width = c.height = size;
    var ctx = c.getContext("2d"), img = ctx.createImageData(size, size), cell = size / n;
    var seed = 11, pts = [], i, j;
    function rnd() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }
    for (j = 0; j < n; j++) for (i = 0; i < n; i++)
      pts.push([(i + 0.12 + 0.76 * rnd()) * cell, (j + 0.12 + 0.76 * rnd()) * cell, 0.97 + 0.03 * rnd()]);
    for (var y = 0; y < size; y++) for (var x = 0; x < size; x++) {
      var ci = Math.floor(x / cell), cj = Math.floor(y / cell), d1 = 1e9, d2 = 1e9, b = 1;
      for (var dj = -1; dj <= 1; dj++) for (var di = -1; di <= 1; di++) {
        var ii = ci + di, jj = cj + dj, ox = 0, oy = 0;
        if (ii < 0) { ii += n; ox = -size; } else if (ii >= n) { ii -= n; ox = size; }
        if (jj < 0) { jj += n; oy = -size; } else if (jj >= n) { jj -= n; oy = size; }
        var p = pts[jj * n + ii], dx = p[0] + ox - x, dy = p[1] + oy - y, d = dx * dx + dy * dy;
        if (d < d1) { d2 = d1; d1 = d; b = p[2]; } else if (d < d2) d2 = d;
      }
      var edge = Math.min(1, (Math.sqrt(d2) - Math.sqrt(d1)) / (cell * 0.16));
      var dome = 1 - 0.045 * Math.min(1, Math.sqrt(d1) / (cell * 0.72));
      var v = Math.round(255 * (0.885 + 0.115 * edge) * b * dome), k = (y * size + x) * 4;
      img.data[k] = img.data[k + 1] = img.data[k + 2] = v; img.data[k + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
    var t = new T.CanvasTexture(c);
    t.wrapS = t.wrapT = T.RepeatWrapping;
    t.anisotropy = Math.min(8, renderer.capabilities.getMaxAnisotropy());
    return t;
  }
  var TILE = 84;                       // мм на один повтор текстури (16 кульок → ~5 мм кулька)
  var beads = beadTexture(256, 16);

  // суцільні деталі з прямокутних шматків; UV — з координат грані, щоб кульки були однакові всюди
  function boxesGeometry(boxes) {
    var P = [], N = [], U = [];
    function quad(a, b, c, d, n) {
      var ax = n[0] ? [2, 1] : n[1] ? [0, 2] : [0, 1];
      [a, b, c, a, c, d].forEach(function (v) {
        P.push(v[0], v[1], v[2]); N.push(n[0], n[1], n[2]); U.push(v[ax[0]] / TILE, v[ax[1]] / TILE);
      });
    }
    boxes.forEach(function (q) {
      var x0 = q[0], y0 = q[1], z0 = q[2], x1 = q[3], y1 = q[4], z1 = q[5];
      quad([x1, y0, z0], [x1, y1, z0], [x1, y1, z1], [x1, y0, z1], [1, 0, 0]);
      quad([x0, y0, z0], [x0, y0, z1], [x0, y1, z1], [x0, y1, z0], [-1, 0, 0]);
      quad([x0, y1, z0], [x0, y1, z1], [x1, y1, z1], [x1, y1, z0], [0, 1, 0]);
      quad([x0, y0, z0], [x1, y0, z0], [x1, y0, z1], [x0, y0, z1], [0, -1, 0]);
      quad([x0, y0, z1], [x1, y0, z1], [x1, y1, z1], [x0, y1, z1], [0, 0, 1]);
      quad([x0, y0, z0], [x0, y1, z0], [x1, y1, z0], [x1, y0, z0], [0, 0, -1]);
    });
    var g = new T.BufferGeometry();
    g.setAttribute("position", new T.Float32BufferAttribute(P, 3));
    g.setAttribute("normal", new T.Float32BufferAttribute(N, 3));
    g.setAttribute("uv", new T.Float32BufferAttribute(U, 2));
    return g;
  }
  // ледь різні відтінки деталей — як на справжніх коробках, де стінки з різних смуг блока
  var tint = { 1: 0xf1f3f6, 2: 0xfbfcfd, 3: 0xffffff, 4: 0xffffff, 5: 0xf8f9fb, 6: 0xf8f9fb };
  var lineMat = new T.LineBasicMaterial({ color: 0x8b95a3, transparent: true, opacity: 0.9 });
  function build(part) {
    var g = new T.Group();
    Object.keys(part.parts).forEach(function (pid) {
      var m = new T.Mesh(boxesGeometry(part.parts[pid]), new T.MeshStandardMaterial({
        color: tint[pid] || 0xffffff, map: beads, roughness: 0.97, metalness: 0,
        polygonOffset: true, polygonOffsetFactor: 1, polygonOffsetUnits: 1
      }));
      m.castShadow = true; m.receiveShadow = true;
      g.add(m);
    });
    var pos = new Float32Array(part.edges.length * 6);
    part.edges.forEach(function (e, i) { pos.set(e, i * 6); });
    var lg = new T.BufferGeometry();
    lg.setAttribute("position", new T.BufferAttribute(pos, 3));
    g.add(new T.LineSegments(lg, lineMat));
    return g;
  }

  // м'яка «контактна» тінь під коробкою
  function blob() {
    var s = 256, c = document.createElement("canvas");
    c.width = c.height = s;
    var ctx = c.getContext("2d"), m = 0.2, bw = s * (1 - 2 * m), bh = s * (1 - 2 * m);
    ctx.fillStyle = "#000"; ctx.fillRect(0, 0, s, s);
    ctx.shadowColor = "#fff"; ctx.shadowBlur = s * 0.09; ctx.shadowOffsetX = s * 2;
    ctx.fillStyle = "#fff"; ctx.fillRect(s * m - s * 2, s * m, bw, bh);
    var t = new T.CanvasTexture(c);
    var mat = new T.MeshBasicMaterial({ color: 0x1c232d, alphaMap: t, transparent: true, opacity: 0.3, depthWrite: false });
    var k = 1 / (1 - 2 * m) * 1.02;
    var mesh = new T.Mesh(new T.PlaneGeometry(L * k, W * k), mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.y = 0.6;
    return mesh;
  }

  var root = new T.Group();
  var body = build(D.body);
  var lidMesh = build(D.lid);
  var LID_C = H - TH / 2;              // центр кришки по висоті — навколо нього нахиляємо
  lidMesh.position.y = -LID_C;
  var lid = new T.Group();
  lid.add(lidMesh);
  lid.position.y = LID_C;
  root.add(blob(), body, lid);
  scene.add(root);

  var LIFT = Math.round(H * 0.6);
  var target = new T.Vector3(0, H * 0.6, 0);
  var yaw = -0.62, pitch = 0.5, baseDist = 1860, dist = baseDist;
  var spin = 0, vel = 0, lidVel = 0;
  var lidPos = LIFT, lidTarget = LIFT;   // стартуємо з піднятою кришкою — як на картинці-заставці
  var t0 = performance.now(), lastUser = -1e9, autoLidAt = t0 + 2600;
  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function resize() {
    var w = host.clientWidth, h = host.clientHeight;
    if (!w || !h) return;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    dist = baseDist * Math.max(1, 0.8 / camera.aspect) * (camera.aspect > 1.3 ? 1.06 : 1);   // телефон/вузький екран — трохи відсуваємо камеру
    camera.updateProjectionMatrix();
  }
  if (window.ResizeObserver) new ResizeObserver(resize).observe(host);
  else window.addEventListener("resize", resize);
  resize();

  // керування
  var down = null, moved = 0, downAt = 0;
  function toggleLid(now) { lidTarget = lidTarget > 0 ? 0 : LIFT; autoLidAt = now + 7000; }
  canvas.addEventListener("pointerdown", function (e) {
    down = { x: e.clientX, y: e.clientY, id: e.pointerId, type: e.pointerType };
    moved = 0; downAt = performance.now(); vel = 0;
    lastUser = downAt;
    host.classList.add("dragging");
    try { canvas.setPointerCapture(e.pointerId); } catch (err) {}
  });
  canvas.addEventListener("pointermove", function (e) {
    if (!down || e.pointerId !== down.id) return;
    var dx = e.clientX - down.x, dy = e.clientY - down.y, now = performance.now();
    moved += Math.abs(dx) + Math.abs(dy);
    yaw += dx * 0.0085;
    vel = dx * 0.0085 / Math.max(0.008, (now - lastUser) / 1000);
    if (down.type === "mouse") pitch = Math.min(1.1, Math.max(0.14, pitch + dy * 0.005));
    down.x = e.clientX; down.y = e.clientY;
    lastUser = now;
  });
  function up(e) {
    if (!down) return;
    var now = performance.now();
    if (e.type === "pointerup" && moved < 7 && now - downAt < 450) { toggleLid(now); vel = 0; }
    if (now - lastUser > 80) vel = 0;
    vel = Math.max(-4, Math.min(4, vel));
    down = null; host.classList.remove("dragging"); lastUser = now;
  }
  canvas.addEventListener("pointerup", up);
  canvas.addEventListener("pointercancel", up);
  host.setAttribute("tabindex", "0");
  host.addEventListener("keydown", function (e) {
    var now = performance.now();
    if (e.key === "ArrowLeft" || e.key === "ArrowRight") { vel = e.key === "ArrowLeft" ? -2.2 : 2.2; lastUser = now; e.preventDefault(); }
    else if (e.key === "Enter" || e.key === " ") { toggleLid(now); lastUser = now; e.preventDefault(); }
  });
  canvas.addEventListener("webglcontextlost", function (e) { e.preventDefault(); host.classList.remove("is-3d"); visible = false; });

  var hint = host.querySelector(".box3d__hint");
  if (hint && window.matchMedia && window.matchMedia("(pointer: coarse)").matches)
    hint.textContent = "Крутіть пальцем · торкніться — кришка";

  var visible = true, running = false, last = performance.now(), shown = false;
  function frame(now) {
    if (!visible) { running = false; return; }
    var dt = Math.min(0.05, Math.max(0, (now - last) / 1000)); last = now;
    var idle = !down && now - lastUser > 2600;

    // обертання: повільне саме по собі + інерція після ривка
    spin += ((idle && !reduce ? 0.26 : 0) - spin) * (1 - Math.exp(-dt * 1.5));
    if (!down) { yaw += (spin + vel) * dt; vel *= Math.exp(-dt * 3.2); }

    // кришка: сама відкривається й закривається, поки ніхто не чіпає
    if (idle && !reduce && now > autoLidAt) {
      lidTarget = lidTarget > 0 ? 0 : LIFT;
      autoLidAt = now + (lidTarget > 0 ? 2900 : 3300);
    }
    lidVel += ((lidTarget - lidPos) * 38 - lidVel * 11.5) * dt;   // м'яка пружина без відскоку
    lidPos += lidVel * dt;
    var tilt = Math.max(0, Math.min(1, (lidPos - 90) / (LIFT - 90)));
    lid.position.y = LID_C + lidPos;
    lid.rotation.z = -0.085 * tilt * tilt * (3 - 2 * tilt);

    root.rotation.y = yaw;
    camera.position.set(0, target.y + dist * Math.sin(pitch), dist * Math.cos(pitch));
    camera.lookAt(target);
    renderer.render(scene, camera);
    if (!shown) { shown = true; host.classList.add("is-3d"); }
    requestAnimationFrame(frame);
  }
  function start() { if (!running && visible) { running = true; last = performance.now(); requestAnimationFrame(frame); } }
  if (window.IntersectionObserver) {
    new IntersectionObserver(function (es) { visible = es[0].isIntersecting; start(); }).observe(host);
  }
  start();
};
if (window.THREE) window.pfBox3d();
